'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
const journeys=[['N','N','N'],['N','S','S'],['S','N','S'],['S','S','N'],['N','N','S'],['S','S','S']];
let variant=OrionProgress.variant('magnets'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,dock='N',last=null,records={},guess=null,solved=false,hintDepth=0,hintOpen=false,state='ready',saveFailed=false;
function challenge(v=variant,s=stage){return {pole:journeys[v][s],goal:s===0?'attract':s===1?'repel':'identify',hidden:s===2};}
function opposite(p){return p==='N'?'S':'N';}
function interaction(a,b){return a===b?'repel':'attract';}
function flip(){if(solved)return;dock=opposite(dock);last=null;state='ready';render();}
function test(){if(solved)return;last=interaction(dock,challenge().pole);records[dock]=last;state='observed';render();}
function selectPole(p){if(solved||!['N','S'].includes(p)||stage!==2)return;guess=p;state='ready';render();}
function resetTrial(){dock='N';last=null;records={};guess=null;solved=false;hintDepth=0;hintOpen=false;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('magnets')){variant=v;stage=0;resetTrial();}
function check(){if(solved)return;const q=challenge();if(q.hidden&&(!records.N||!records.S))state='needBoth';else if(q.hidden&&!guess)state='needGuess';else if(!q.hidden&&!last)state='needTest';else if(q.hidden?guess!==q.pole:last!==q.goal)state='wrong';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('compass');}render();if(solved&&stage<2)$('next').focus();}
function resultName(r){return r==='attract'?t('Pulls toward dock ←','拉向碼頭 ←'):t('Pushes away from dock →','推離碼頭 →');}
function magnet(x,y,left,right,hidden=false){return [left,right].map((p,i)=>`<rect x="${x+i*48}" y="${y}" width="48" height="42" rx="4" fill="${hidden?'#5a676c':p==='N'?'#ad4e42':'#376eaa'}" stroke="#e6d5a6"/><text x="${x+i*48+24}" y="${y+28}" text-anchor="middle" fill="white" font-size="23">${hidden?'?':p}</text>`).join('');}
function drawing(){const q=challenge(),x=last==='attract'?195:last==='repel'?295:245;return `<svg viewBox="0 0 460 250" role="img" aria-label="${t(`Dock facing pole ${dock}; ferry facing pole ${q.hidden&&!solved?'hidden':q.pole}. ${last?resultName(last):'Not tested.'}`,`碼頭相對磁極 ${dock}；渡船相對磁極 ${q.hidden&&!solved?'隱藏':q.pole}。${last?resultName(last):'尚未測試。'}`)}"><path d="M10 190Q60 180 110 190T210 190T310 190T450 190M10 215Q60 205 110 215T210 215T310 215T450 215" fill="none" stroke="#549baf" stroke-width="3"/><path d="M0 160H170V240H0Z" fill="#627170"/><text x="70" y="220" fill="#fff0c3" text-anchor="middle">${t('Fixed dock','固定碼頭')}</text>${magnet(48,115,opposite(dock),dock)}<g class="ferry" style="transform:translateX(${x}px)"><path d="M-10 160H116L98 185H8Z" fill="#a17b4a" stroke="#e2c795" stroke-width="3"/>${magnet(0,115,q.pole,opposite(q.pole),q.hidden&&!solved)}<text x="48" y="205" fill="#fff0c3" text-anchor="middle">${t('Ferry','渡船')}</text></g><text x="250" y="75" text-anchor="middle" fill="#ffe29d" font-size="32">${last?(last==='attract'?'←':'→'):'?'}</text></svg>`;}
function hints(){return[t('Look at the two ends facing each other, not the far ends. Test, flip, and test again.','觀察互相朝向的兩個末端，不是遠端。測試、翻轉，再測試。'),t('Compare N facing N with N facing S. Which test pulls, and which pushes?','比較 N 對 N 和 N 對 S。哪次拉近，哪次推開？'),t('Like poles repel; opposite poles attract. If dock N pushes the mystery magnet away, its facing pole is N. If it pulls, the facing pole is S.','同極相斥，異極相吸。若碼頭 N 推開神秘磁石，它朝向碼頭的是 N；若拉近，就是 S。')];}
function render(){const q=challenge(),complete=solved&&stage===2,p=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Magnet Ferry · Orion','磁石渡船 · Orion');$('stageTitle').textContent=t(`Lock ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 道船鎖 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Harbour seals · ${p} / 3`,`港灣封印 · ${p} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<p?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);$('diagram').innerHTML=drawing();$('facing').textContent=t(`Dock end facing ferry: ${dock}. Ferry end facing dock: ${q.hidden&&!solved?'?':q.pole}.`,`碼頭朝向渡船的末端：${dock}。渡船朝向碼頭的末端：${q.hidden&&!solved?'?':q.pole}。`);$('flip').disabled=$('test').disabled=solved;
$('goal').textContent=q.hidden?t('Test BOTH dock poles, then identify the hidden ferry pole facing the dock.','用碼頭的兩個磁極各測試一次，再辨認渡船朝向碼頭的隱藏磁極。'):q.goal==='attract'?t('Make the ferry move TOWARD the dock. Test your arrangement, then check the lock.','讓渡船移向碼頭。測試你的排列，再檢查船鎖。'):t('Make the ferry move AWAY from the dock. Test your arrangement, then check the lock.','讓渡船離開碼頭。測試你的排列，再檢查船鎖。');$('reading').textContent=last?resultName(last):t('Ready for a new test.','準備進行新測試。');$('records').innerHTML=['N','S'].map(p=>`<p>${t('Dock','碼頭')} ${p}: ${records[p]?resultName(records[p]):t('Not tested','尚未測試')}</p>`).join('');$('guessPanel').hidden=!q.hidden;for(const p of ['N','S']){$('guess'+p).setAttribute('aria-pressed',String(guess===p));$('guess'+p).disabled=solved;}
const messages={ready:['Flip or test to explore. Your records stay until you clear them.','翻轉或測試，探索磁石。紀錄會保留，直到你清除。'],observed:['Observation recorded. Compare the facing poles and the motion.','觀察已記錄。比較相對的磁極和移動方向。'],needBoth:['Test once with dock N and once with dock S before identifying the hidden pole.','先用碼頭 N 和 S 各測試一次，再辨認隱藏磁極。'],needGuess:['Choose N or S using your test records.','根據測試紀錄，選 N 或 S。'],needTest:['Test this arrangement first. Flipping needs a fresh test.','先測試這個排列。翻轉後需要重新測試。'],wrong:['That does not match the request. Compare your records and try again.','這不符合要求。比較紀錄，再試一次。'],success:['The lock releases. Your magnetic evidence fits!','船鎖解開了，你的磁力證據吻合！']};$('feedback').textContent=t(...messages[state]);$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintOpen));$('hints').hidden=!hintOpen;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('')+`<li class="close-clues"><button data-close>${t('Close clues','關閉提示')}</button></li>`;$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('compass')?t('Compass Sigil saved in your collection.','磁向符印已存入收藏。'):'';}
$('flip').onclick=flip;$('test').onclick=test;for(const p of ['N','S'])$('guess'+p).onclick=()=>selectPole(p);$('hints').onclick=e=>{if(e.target.closest('button[data-close]')){hintOpen=false;render();$('hint').focus();}};window.addEventListener('keydown',e=>{if(e.key==='Escape'&&hintOpen){hintOpen=false;render();$('hint').focus();}});$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);hintOpen=true;render();};
$('replay').onclick=()=>{const v=OrionProgress.nextVariant('magnets',variant);observedVariant=OrionProgress.variant('magnets');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('compass');render();};function syncProgress(){const v=OrionProgress.variant('magnets'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('compass')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
